 private FrameLayout avatar(JSONObject p,int size,String pathKey,String nameKey){FrameLayout outer=new FrameLayout(this);FrameLayout frame=new FrameLayout(this);outer.addView(frame,new FrameLayout.LayoutParams(-1,-1));frame.setBackground(shape(alt,100,line));frame.setClipToOutline(true);String name=p==null?"":p.optString(nameKey);TextView initials=txt(name.isEmpty()?"C":name.substring(0,1).toUpperCase(Locale.ROOT),Math.max(13,size/3),true,fg);initials.setGravity(Gravity.CENTER);frame.addView(initials,new FrameLayout.LayoutParams(-1,-1));String path=p==null?"":p.optString(pathKey,"");if(!path.isEmpty()&&!"null".equals(path)){ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(im,new FrameLayout.LayoutParams(-1,-1));android.graphics.Bitmap cached=avatarCache.get(path);if(cached!=null)im.setImageBitmap(cached);else images.execute(()->{try{String url=api.signed("entre-avatars",path);java.net.URLConnection conn=new java.net.URL(url).openConnection();conn.setConnectTimeout(7000);conn.setReadTimeout(7000);try(java.io.InputStream in=conn.getInputStream()){android.graphics.Bitmap b=android.graphics.BitmapFactory.decodeStream(in);if(b!=null){avatarCache.put(path,b);main.post(()->{if(!isDestroyed())im.setImageBitmap(b);});}}}catch(Exception ignored){}});}outer.setLayoutParams(new LinearLayout.LayoutParams(dp(size),dp(size)));applyPremiumAvatar(outer,p,size);return outer;}
 private final Map<String,Boolean> badgeCache=new HashMap<>();
 private final Map<String,List<FrameLayout>> badgePending=new LinkedHashMap<>();
 private boolean badgeScheduled;private long badgeEpoch;
 private void applyPremiumAvatar(FrameLayout frame,JSONObject p,int size){
  if(p==null)return;String id=p.optString("author_id",p.optString("id",""));
  if(id.equals(uid)&&!uid.isEmpty()){if(premium!=null&&premium.optBoolean("active"))markPremium(frame);return;}
  if(p.has("premium")){if(p.optBoolean("premium"))markPremium(frame);return;}
  if(id.isEmpty()||uid.isEmpty())return;
  long now=SystemClock.elapsedRealtime();if(now-badgeEpoch>60000){badgeCache.clear();badgeEpoch=now;}
  if(badgeCache.containsKey(id)){if(Boolean.TRUE.equals(badgeCache.get(id)))markPremium(frame);return;}
  badgePending.computeIfAbsent(id,k->new ArrayList<>()).add(frame);
  if(!badgeScheduled){badgeScheduled=true;main.postDelayed(this::loadPremiumBadges,80);}
 }
 private void loadPremiumBadges(){
  badgeScheduled=false;if(badgePending.isEmpty()||isDestroyed())return;Map<String,List<FrameLayout>> work=new LinkedHashMap<>(badgePending);badgePending.clear();String owner=uid;if(owner.isEmpty())return;
  io.execute(()->{try{Object data=api.rpc("entre_premium_badges",obj("_ids",new JSONArray(work.keySet())));if(!(data instanceof JSONArray))return;JSONArray ids=(JSONArray)data;Set<String> active=new HashSet<>();for(int i=0;i<ids.length();i++)active.add(ids.optString(i));main.post(()->{if(isDestroyed()||!owner.equals(uid))return;for(String id:work.keySet()){boolean paid=active.contains(id);badgeCache.put(id,paid);if(paid)for(FrameLayout frame:work.get(id))markPremium(frame);}});}catch(Exception ignored){}});
 }
 private void markPremium(FrameLayout frame){frame.setForeground(new PremiumMark());}
