 private <T> void task(Work<T> work,Result<T> result){
  if(busy||isFinishing())return;busy=true;long generation=++requestGeneration;
  if(status!=null)status.setText("Carregando…");
  io.execute(()->{try{T v=work.run();main.post(()->{if(isDestroyed()||generation!=requestGeneration)return;busy=false;if(status!=null)status.setText("");result.done(v);});}
   catch(Exception ex){main.post(()->{if(isDestroyed()||generation!=requestGeneration)return;busy=false;sound("error");String msg=errorMessage(ex);if(ex instanceof Gate){searching=false;gate(msg);}else if(ex instanceof ConnectApi.ApiException&&((ConnectApi.ApiException)ex).invalidSession()&&!api.hasSession()&&!uid.isEmpty()){uid="";profile=null;auth(false,"Sua sessão expirou. Entre novamente.");}else {if(cancelling){cancelling=false;cancelPending=true;searching=false;encounters();}notice(msg);}});}});
 }
