 private String[] downloadCities(String uf)throws Exception{if(!validUF(uf))throw new IllegalArgumentException();java.net.HttpURLConnection conn=(java.net.HttpURLConnection)new java.net.URL("https://servicodados.ibge.gov.br/api/v1/localidades/estados/"+uf+"/municipios").openConnection();try{conn.setConnectTimeout(8000);conn.setReadTimeout(10000);conn.setInstanceFollowRedirects(false);if(conn.getResponseCode()!=200)throw new java.io.IOException();try(java.io.InputStream in=conn.getInputStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>2000000)throw new java.io.IOException();out.write(buf,0,n);}JSONArray rows=new JSONArray(out.toString("UTF-8"));if(rows.length()<1||rows.length()>1500)throw new java.io.IOException();String[] cities=new String[rows.length()];for(int i=0;i<rows.length();i++)cities[i]=rows.getJSONObject(i).getString("nome");Arrays.sort(cities,java.text.Collator.getInstance(new Locale("pt","BR")));return cities;}}finally{conn.disconnect();}}
